WITH remaining_keys AS (SELECT product_id FROM inventory EXCEPT ALL SELECT product_id FROM inventory WHERE store_id = 3), reconciled AS (SELECT s.* FROM inventory s INNER JOIN remaining_keys k ON s.product_id = k.product_id) SELECT DATE_TRUNC('MONTH', last_restock) AS activity_month, MAX(quantity) AS max_quantity, ROUND(AVG(quantity), 2) AS avg_quantity, BIT_AND(quantity) AS quantity_bit_and, STDDEV_SAMP(quantity) AS quantity_stddev, COUNT(*) AS event_count FROM reconciled GROUP BY DATE_TRUNC('MONTH', last_restock) HAVING quantity_bit_and > 1
